using System; using System.Collections.Generic; using System.IO; using System.Linq; using System.Net; using System.Net.Sockets; using System.Text; using System.Threading; using EmulatorHub;
class IntegrationExpansionTests {
 static int checks;
 static void Check(bool value,string label) { checks++;if(!value)throw new Exception(label); }
 static void Reject(Action action,string label) { bool rejected=false;try { action(); } catch(IOException) { rejected=true; } Check(rejected,label); }
 static int Main() { try { Run();Console.WriteLine("PASS: "+checks+" metadata, achievements, declarative extensions, import privacy and companion checks.");return 0; }catch(Exception e){Console.WriteLine(e);return 1;} }
 static string Send(int port,string target,string method) { using(TcpClient client=new TcpClient()) { client.Connect(IPAddress.Loopback,port);client.ReceiveTimeout=5000;client.SendTimeout=5000;using(NetworkStream stream=client.GetStream()) { byte[] request=Encoding.ASCII.GetBytes(method+" "+target+" HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n");stream.Write(request,0,request.Length);using(StreamReader reader=new StreamReader(stream,Encoding.UTF8))return reader.ReadToEnd(); } } }
 static void Run() {
  LibraryData data=new LibraryData { Games=new List<GameEntry>(),Emulators=new List<EmulatorProfile>(),PlaySessions=new List<PlaySession>() };Check(IntegrationData.Ensure(data).Extensions.Count==0&&data.Integrations.Achievements.Count==0,"old libraries receive empty optional integration lists");
  string achievements="{\"Results\":[null,{\"GameID\":0},{\"GameID\":1,\"Title\":\"One\",\"MaxPossible\":20,\"NumAwarded\":30,\"NumAwardedHardcore\":-1},{\"GameID\":2,\"MaxPossible\":-9,\"NumAwarded\":5}],\"Total\":2}";AchievementResponse progress=IntegrationData.ParseAchievements(achievements);Check(progress.Results.Count==2&&progress.Results[0].NumAwarded==20&&progress.Results[0].NumAwardedHardcore==0,"achievement counters clamped and invalid entries dropped");Check(progress.Results[1].MaxPossible==0&&progress.Results[1].NumAwarded==0,"negative achievement totals cannot render invalid percentages");Reject(delegate{IntegrationData.ParseAchievements("{}");},"missing completion list rejected");Reject(delegate{IntegrationData.FetchAchievements("", "",CancellationToken.None);},"blank credentials rejected before network request");
  List<MetadataRecord> records=IntegrationData.ParseCatalog("[null,{\"Title\":\"Pokemon X\",\"Description\":\"Description\",\"Genre\":\"RPG\",\"Developer\":\"Studio\",\"ReleaseYear\":\"2013\",\"Source\":\"Fixture\"},{\"Title\":\" \"}]");Check(records.Count==1,"metadata catalog excludes empty records");GameEntry game=new GameEntry { Title="Pokémon X",Path="keep.rom",TitleIsCustom=true,ArtworkPath="keep.png",Genre="old",TotalPlaySeconds=300 };records[0].Title="Pokémon X";Check(IntegrationData.Match(game,records)==records[0],"unique normalized title matches metadata");Check(IntegrationData.Match(game,new[]{records[0],records[0]})==null,"ambiguous metadata matches require review");Check(IntegrationData.Match(new GameEntry{Title="!!!"},new[]{new MetadataRecord{Title="???"}})==null,"punctuation-only titles cannot match unrelated metadata");Check(IntegrationData.Match(game,null)==null,"missing optional catalog produces no metadata match");IntegrationData.ApplyMetadata(game,records[0]);Check(game.Title=="Pokémon X"&&game.Path=="keep.rom"&&game.ArtworkPath=="keep.png"&&game.TotalPlaySeconds==300,"metadata preserves custom title file artwork and play history");Check(game.Genre=="RPG"&&game.Description=="Description"&&game.Extras.MetadataSource=="Fixture","reviewed metadata fields applied");Reject(delegate{IntegrationData.ParseCatalog(new string(' ',4*1024*1024+1));},"oversized metadata input rejected");Reject(delegate{IntegrationData.FetchJson("http://localhost/catalog",CancellationToken.None);},"unencrypted catalog rejected without fetching");Reject(delegate{IntegrationData.FetchJson("https://user:secret@example.com/catalog",CancellationToken.None);},"embedded URL credentials rejected without fetching");
  string root=Path.Combine(Path.GetTempPath(),"FishBowlIntegrations-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string manifest=Path.Combine(root,"extension.json"),catalog=Path.Combine(root,"games.json");File.WriteAllText(catalog,"[{\"Title\":\"Local game\"}]");File.WriteAllText(manifest,Json.Serialize(new ExtensionManifest { Id="fixture",Name="Fixture",Kind="Metadata",CatalogPath="games.json" }));ExtensionManifest extension=IntegrationData.LoadExtension(manifest);Check(extension.CatalogPath==catalog&&IntegrationData.ReadCatalog(extension,CancellationToken.None).Count==1,"relative declarative catalog resolved against manifest folder");Reject(delegate{IntegrationData.ValidateExtension(new ExtensionManifest{Id="../escape",Name="Bad",Kind="Metadata",CatalogPath=catalog});},"extension identifier traversal rejected");Reject(delegate{IntegrationData.ValidateExtension(new ExtensionManifest{Id="code",Name="Bad",Kind="Executable",CatalogPath=catalog});},"executable extension kinds rejected");Reject(delegate{IntegrationData.ValidateExtension(new ExtensionManifest{Id="http",Name="Bad",Kind="Metadata",CatalogUrl="http://example.com"});},"extension catalog must use HTTPS");Reject(delegate{IntegrationData.ValidateExtension(new ExtensionManifest{Id="dot",Name="Bad",Kind="Emulator",Extensions=new List<string>{"."}});},"empty dot extension rejected");Reject(delegate{IntegrationData.ValidateExtension(new ExtensionManifest{Id="dots",Name="Bad",Kind="Emulator",Extensions=new List<string>{"..exe"}});},"multiple leading dots rejected");Reject(delegate{IntegrationData.ValidateExtension(new ExtensionManifest{Id="large",Name="Bad",Kind="Emulator",Extensions=Enumerable.Repeat(".rom",129).ToList()});},"extension list bounded");File.WriteAllText(manifest,new string(' ',1024*1024+1));Reject(delegate{IntegrationData.LoadExtension(manifest);},"oversized extension manifest rejected");
  string exe=Path.Combine(root,"game.exe"),rom=Path.Combine(root,"game.rom"),batch=Path.Combine(root,"game.cmd");File.WriteAllText(exe,"fixture");File.WriteAllText(rom,"fixture");File.WriteAllText(batch,"fixture");GameEntry imported=new GameEntry { Id="remote",Title="Imported",Path=exe,EmulatorId="remote",PreferredEmulatorId="remote",RequiresEmulatorAssignment=false,ArtworkPath="private",Tools=new GameToolsSettings { ModProfiles=new List<ModProfile>{ new ModProfile{Applied=true,DestinationFolder="private",BackupFolder="private"} } },Saves=new List<GameSaveEntry>(),Extras=new GameExtras { Native=true,WorkingDirectory="private",TrailerUrl="secret" },TotalPlaySeconds=900,ControllerProfileId="remote" };List<GameEntry> prepared=IntegrationData.PrepareImport(data,new[]{imported,imported,new GameEntry{Title="No file",Path=Path.Combine(root,"missing")},new GameEntry{Title="Script",Path=batch,Extras=new GameExtras{Native=true}}});Check(prepared.Count==1&&prepared[0].Id!="remote"&&prepared[0].Extras.Native,"native catalog deduplicated with fresh local identifier");GameEntry clean=prepared[0];Check(clean.Tools==null&&clean.Saves==null&&clean.EmulatorId==null&&clean.PreferredEmulatorId==null&&clean.ControllerProfileId==null&&clean.ArtworkPath==null&&clean.TotalPlaySeconds==0,"catalog cannot inject operations restore journals assignments or history");Check(clean.Extras.WorkingDirectory==null&&clean.Extras.TrailerUrl==null&&clean.TitleIsCustom,"catalog extras restricted to reviewed native flag");prepared=IntegrationData.PrepareImport(data,new[]{new GameEntry{Title="ROM",Path=rom},new GameEntry{Title="Relative",Path="game.exe"}});Check(prepared.Count==1&&prepared[0].RequiresEmulatorAssignment,"emulated imports require local emulator assignment and absolute file paths");Check(IntegrationData.PrepareImport(data,null).Count==0,"null catalog safely produces empty import");
  data.Games.Add(new GameEntry { Title="<img src=x onerror=alert(1)>",Path="PRIVATE-ROM-PATH",ArtworkPath="PRIVATE-ART-PATH",Notes="PRIVATE-NOTES",Extras=new GameExtras{Fields=new Dictionary<string,string>{{"password","PRIVATE-CREDENTIAL"}}},Favorite=true,TotalPlaySeconds=120 });data.Games.Add(null);data.Integrations.AchievementUser="PRIVATE-USERNAME";string snapshot=IntegrationData.CompanionSnapshot(data);Check(!snapshot.Contains("PRIVATE-"),"companion snapshot excludes paths notes account names and credentials");Check(snapshot.Contains("onerror")&&snapshot.Contains("seconds"),"companion retains library titles and play statistics as JSON data");
  Check(CompanionServer.PrivateAddress(IPAddress.Loopback)&&CompanionServer.PrivateAddress(IPAddress.Parse("10.0.0.1"))&&CompanionServer.PrivateAddress(IPAddress.Parse("172.31.255.254")),"private interface addresses accepted");Check(!CompanionServer.PrivateAddress(IPAddress.Any)&&!CompanionServer.PrivateAddress(IPAddress.Parse("8.8.8.8"))&&!CompanionServer.PrivateAddress(IPAddress.Parse("172.32.0.1")),"public and wildcard interface addresses excluded");
  using(CompanionServer server=new CompanionServer()) { Reject(delegate{server.Start(IPAddress.Any,0);},"wildcard binding rejected");Reject(delegate{server.Start(IPAddress.Parse("8.8.8.8"),0);},"public binding rejected");Reject(delegate{server.Start(IPAddress.Loopback,80);},"reserved port rejected");server.Update(snapshot);server.Start(IPAddress.Loopback,0);string pair=server.PairCode;Check(pair.Length==48&&server.Running,"companion starts with random pairing credential");Check(Send(server.Port,"/library.json","GET").StartsWith("HTTP/1.1 401"),"unpaired browser cannot read library");Check(Send(server.Port,"/library.json?pair=wrong","GET").StartsWith("HTTP/1.1 401"),"invalid pairing cannot read library");string valid=Send(server.Port,"/library.json?pair="+pair,"GET");Check(valid.StartsWith("HTTP/1.1 200")&&valid.Contains(snapshot)&&valid.Contains("Cache-Control: no-store"),"paired browser receives read-only snapshot without caching");Check(Send(server.Port,"/library.json?pair="+pair,"POST").StartsWith("HTTP/1.1 405"),"companion cannot accept write operations");Check(Send(server.Port,"/missing?pair="+pair,"GET").StartsWith("HTTP/1.1 404"),"unknown paired routes rejected");string page=Send(server.Port,"/?pair="+pair,"GET");Check(page.Contains("title.textContent=")&&!page.Contains("onerror=alert")&&!page.Contains("innerHTML"),"untrusted titles never interpolated into companion HTML");Check(page.Contains("Content-Security-Policy:")&&page.Contains("Referrer-Policy: no-referrer"),"companion restricts resource loading and pairing referrer leaks");int port=server.Port;using(TcpClient accepted=new TcpClient()) { accepted.Connect(IPAddress.Loopback,port);var clients=typeof(CompanionServer).GetField("clients",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);DateTime deadline=DateTime.UtcNow.AddSeconds(2);while((int)clients.GetValue(server)==0&&DateTime.UtcNow<deadline)Thread.Sleep(10);Check((int)clients.GetValue(server)>0,"shutdown regression uses an accepted socket");server.Dispose();try { NetworkStream stream=accepted.GetStream();byte[] request=Encoding.ASCII.GetBytes("GET /library.json HTTP/1.1\r\nHost: localhost\r\n\r\n");stream.Write(request,0,request.Length);accepted.ReceiveTimeout=3000;string stopped=new StreamReader(stream).ReadToEnd();Check(!stopped.Contains(snapshot),"stopped server cannot authorize already accepted unpaired socket"); } catch(IOException) { Check(true,"stopped server closes accepted connection"); } }Check(!server.Running&&string.IsNullOrEmpty(server.PairCode),"stop clears active pairing credential"); }
 }
